        "code": "# A passive scanner never attacks: it only reads responses that already exist.\nRESPONSE = {\n    \"url\": \"http://localhost:3000/\",\n    \"status\": 200,\n    \"headers\": {\n        \"Content-Type\": \"text/html; charset=UTF-8\",\n        \"X-Content-Type-Options\": \"nosniff\",\n        \"X-Frame-Options\": \"SAMEORIGIN\",\n        \"Access-Control-Allow-Origin\": \"*\",\n        \"Set-Cookie\": \"session=abc123; Path=/\",\n    },\n}\n\nEXPECTED_HEADERS = {\n    \"Content-Security-Policy\": \"limits where scripts may come from (XSS damage control)\",\n    \"Strict-Transport-Security\": \"forces browsers to come back over HTTPS\",\n    \"X-Content-Type-Options\": \"stops MIME type sniffing\",\n    \"X-Frame-Options\": \"blocks clickjacking through iframes\",\n}\n\n\ndef passive_scan(response):\n    findings = []\n    headers = response[\"headers\"]\n    for name, reason in EXPECTED_HEADERS.items():\n        if name not in headers:\n            findings.append(f\"WARN  missing header {name}: {reason}\")\n    cookie = headers.get(\"Set-Cookie\", \"\").lower()\n    if cookie:\n        for flag in (\"httponly\", \"secure\", \"samesite\"):\n            if flag not in cookie:\n                findings.append(f\"WARN  cookie without {flag} flag\")\n    if headers.get(\"Access-Control-Allow-Origin\") == \"*\":\n        findings.append(\"WARN  CORS allows any origin (*)\")\n    return findings\n\n\nresults = passive_scan(RESPONSE)\nfor line in results:\n    print(line)\nprint(f\"{len(results)} finding(s), 0 attack request sent\")\n",
