        "code": "import re\n\nRESPONSE = {\n    \"url\": \"http://localhost:4280/login.php\",\n    \"headers\": {\n        \"Server\": \"Apache/2.4.57 (Debian)\",\n        \"X-Powered-By\": \"PHP/8.2.12\",\n        \"Content-Type\": \"text/html; charset=utf-8\",\n        \"Set-Cookie\": \"PHPSESSID=abc123; path=/\",\n    },\n}\n\n# A version number looks like 2.4 or 8.2.12\nVERSION = re.compile(r\"\\d+\\.\\d+(\\.\\d+)?\")\n\n\ndef leaky_headers(response):\n    findings = []\n    for name in (\"Server\", \"X-Powered-By\"):\n        value = response[\"headers\"].get(name, \"\")\n        if VERSION.search(value):\n            findings.append(f\"WARN  {name} leaks a version: {value}\")\n    return findings\n\n\n# Passive check: it only reads a response, no attack request is sent\nfor line in leaky_headers(RESPONSE):\n    print(line)\n",
